import AppKit

/// Trackpad back/forward swipes.
///
/// Uses the `.swipe` event rather than raw scroll deltas so macOS decides what counts as a swipe:
/// the user's "Swipe between pages" preference (two fingers, three fingers, or either) is honoured
/// for free, and a horizontal two-finger *scroll* over a wide board is not mistaken for a gesture.
///
/// The consequence worth knowing: if that preference is off, no `.swipe` events are generated by
/// anything and this correctly does nothing. It is System Settings > Trackpad > More Gestures.
///
/// Direction follows AppKit's convention, where `deltaX` is positive for a swipe toward the left.
/// That maps to browser behaviour -- swipe right to go back, left to go forward.
final class SwipeMonitor: ObservableObject {
    private var token: Any?

    enum Direction { case back, forward }

    func install(_ handler: @escaping (Direction) -> Bool) {
        remove()
        token = NSEvent.addLocalMonitorForEvents(matching: .swipe) { event in
            guard event.deltaX != 0 else { return event }
            let direction: Direction = event.deltaX > 0 ? .forward : .back
            return handler(direction) ? nil : event
        }
    }

    func remove() {
        if let token { NSEvent.removeMonitor(token) }
        token = nil
    }

    deinit {
        if let token { NSEvent.removeMonitor(token) }
    }
}
